     9	export function diversify<T extends { documentId: string }>(
    10	  ranked: T[],
    11	  limit: number,
    12	  perDocument = 2,
    13	): T[] {
    14	  const counts = new Map<string, number>(),
    15	    result: T[] = [];
    16	  for (const item of ranked) {
    17	    const count = counts.get(item.documentId) || 0;
    18	    if (count >= perDocument) continue;
    19	    counts.set(item.documentId, count + 1);
    20	    result.push(item);
    21	    if (result.length >= limit) break;
    22	  }
    23	  return result;
    24	}
    25	export async function searchDocuments(
    26	  query: string,
    27	  role = 'customer',
    28	  limit = 5,
    29	  includeArchived = false,
    30	): Promise<SearchResult[]> {
    31	  const meta = appDb().prepare('SELECT value FROM meta WHERE key=?').get('index-model') as
    32	    { value: string } | undefined;
    33	  if (!meta) throw new Error('No document index. Run npm run setup or npm run ingest.');
    34	  if (meta.value !== config.embeddingModel)
    35	    throw new Error('The model does not match the index. Re-ingest the documents.');
    36	  const [queryVector] = await embedTexts([query]);
    37	  const ranked = allChunks()
    38	    .filter(
    39	      (c) => (role === 'operator' || c.audience === 'public') && (includeArchived || isCurrent(c)),
    40	    )
    41	    .map(({ vector, ...c }) => {
    42	      if (vector!.length !== queryVector.length)
    43	        throw new Error('Incompatible embedding dimensions.');
    44	      const score = vector!.reduce((sum, v, i) => sum + v * queryVector[i], 0);
    45	      return { ...c, score };
    46	    })
    47	    .sort((a, b) => b.score - a.score);
    48	  return diversify(ranked, limit);
    49	}
