     3	function splitLong(paragraph: string, max: number): string[] {
     4	  const sentences = paragraph.match(/[^.!?]+[.!?]+|\S[^.!?]*$/g) || [paragraph];
     5	  const parts: string[] = [];
     6	  let buffer = '';
     7	  for (const sentence of sentences) {
     8	    if (buffer.length + sentence.length > 700 && buffer) {
     9	      parts.push(buffer.trim());
    10	      buffer = '';
    11	    }
    12	    buffer += sentence;
    13	    while (buffer.length > max) {
    14	      parts.push(buffer.slice(0, max).trim());
    15	      buffer = buffer.slice(max);
    16	    }
    17	  }
    18	  if (buffer.trim()) parts.push(buffer.trim());
    19	  return parts;
    20	}
    21	export function chunkDocument(doc: DocumentRecord, text: string): Chunk[] {
    22	  const header = `${doc.title} (${doc.id} v${doc.version})\n`;
    23	  const paragraphs = text
    24	    .split(/\n\s*\n/)
    25	    .map((p) => p.trim())
    26	    .filter(Boolean);
    27	  const groups: string[] = [];
    28	  let buffer = '';
    29	  for (const paragraph of paragraphs) {
    30	    if (paragraph.length > 700) {
    31	      if (buffer) {
    32	        groups.push(buffer);
    33	        buffer = '';
    34	      }
    35	      groups.push(...splitLong(paragraph, 1400 - header.length));
    36	    } else if (buffer && buffer.length + paragraph.length + 2 > 700) {
    37	      groups.push(buffer);
    38	      buffer = paragraph;
    39	    } else {
    40	      buffer = buffer ? `${buffer}\n\n${paragraph}` : paragraph;
    41	    }
    42	  }
    43	  if (buffer) groups.push(buffer);
    44	  return groups.map((group, index) => {
    45	    const body = `${header}${group}`;
    46	    return {
    47	      id: createHash('sha256').update(`${doc.id}:${index}:${body}`).digest('hex').slice(0, 24),
    48	      documentId: doc.id,
    49	      text: body,
    50	      title: doc.title,
    51	      version: doc.version,
    52	      validFrom: doc.validFrom,
    53	      validTo: doc.validTo,
    54	      audience: doc.audience,
    55	    };
    56	  });
    57	}
